            # Top bar, centered stem below: T points down.
            if (all(grid[r][c + dc] == 2 for dc in range(3))
                    and grid[r + 1][c + 1] == 2):
                down += 1
            # Bottom bar, centered stem above: T points up.
            if (all(grid[r + 2][c + dc] == 2 for dc in range(3))
